import{_ as t,o,c as n,l as r,t as i,N as a}from"./chunks/framework.Bbd9fWQx.js";const b=JSON.parse('{"title":"gitignore | x-cmd man (git man5) | Specifies intentionally untracked files to ignore","titleTemplate":false,"description":"x-cmd man (git man5 Manual Page) | gitignore - Specifies intentionally untracked files to ignore","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"gitignore | x-cmd man (git man5) | Specifies intentionally untracked files to ignore"}],["meta",{"name":"og:description","content":"x-cmd man (git man5 Manual Page) | gitignore - Specifies intentionally untracked files to ignore"}]]},"headers":[],"params":{"isMan":true,"man":"gitignore","category":"git man5","desc":"Specifies intentionally untracked files to ignore"},"relativePath":"git/man5/gitignore.md","filePath":"git/man5/gitignore.md"}'),s={name:"git/man5/gitignore.md"},l={class:"visually-hidden"},c=a(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>gitignore - Specifies intentionally untracked files to ignore</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p>$XDG_CONFIG_HOME/git/ignore, $GIT_DIR/info/exclude, .gitignore</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>A <strong>gitignore</strong> file specifies intentionally untracked files that Git should ignore. Files already tracked by Git are not affected; see the NOTES below for details.</p><p>Each line in a <strong>gitignore</strong> file specifies a pattern. When deciding whether to ignore a path, Git normally checks <strong>gitignore</strong> patterns from multiple sources, with the following order of precedence, from highest to lowest (within one level of precedence, the last matching pattern decides the outcome):</p><blockquote><p>·</p><p>Patterns read from the command line for those commands that support them.</p></blockquote><blockquote><p>·</p><p>Patterns read from a <strong>.gitignore</strong> file in the same directory as the path, or in any parent directory (up to the top-level of the working tree), with patterns in the higher level files being overridden by those in lower level files down to the directory containing the file. These patterns match relative to the location of the <strong>.gitignore</strong> file. A project normally includes such <strong>.gitignore</strong> files in its repository, containing patterns for files generated as part of the project build.</p></blockquote><blockquote><p>·</p><p>Patterns read from <strong>$GIT_DIR/info/exclude</strong>.</p></blockquote><blockquote><p>·</p><p>Patterns read from the file specified by the configuration variable <strong>core.excludesFile</strong>.</p></blockquote><p>Which file to place a pattern in depends on how the pattern is meant to be used.</p><blockquote><p>·</p><p>Patterns which should be version-controlled and distributed to other repositories via clone (i.e., files that all developers will want to ignore) should go into a <strong>.gitignore</strong> file.</p></blockquote><blockquote><p>·</p><p>Patterns which are specific to a particular repository but which do not need to be shared with other related repositories (e.g., auxiliary files that live inside the repository but are specific to one user&#39;s workflow) should go into the <strong>$GIT_DIR/info/exclude</strong> file.</p></blockquote><blockquote><p>·</p><p>Patterns which a user wants Git to ignore in all situations (e.g., backup or temporary files generated by the user&#39;s editor of choice) generally go into a file specified by <strong>core.excludesFile</strong> in the user&#39;s <strong>~/.gitconfig</strong>. Its default value is $XDG_CONFIG_HOME/git/ignore. If $XDG_CONFIG_HOME is either not set or empty, $HOME/.config/git/ignore is used instead.</p></blockquote><p>The underlying Git plumbing tools, such as <em>git ls-files</em> and <em>git read-tree</em>, read <strong>gitignore</strong> patterns specified by command-line options, or from files specified by command-line options. Higher-level Git tools, such as <em>git status</em> and <em>git add</em>, use patterns from the sources specified above.</p><h2 id="pattern-format" tabindex="-1">PATTERN FORMAT <a class="header-anchor" href="#pattern-format" aria-label="Permalink to &quot;PATTERN FORMAT&quot;">​</a></h2><blockquote><p>·</p><p>A blank line matches no files, so it can serve as a separator for readability.</p></blockquote><blockquote><p>·</p><p>A line starting with # serves as a comment. Put a backslash (&quot;<strong>\\</strong>&quot;) in front of the first hash for patterns that begin with a hash.</p></blockquote><blockquote><p>·</p><p>Trailing spaces are ignored unless they are quoted with backslash (&quot;<strong>\\</strong>&quot;).</p></blockquote><blockquote><p>·</p><p>An optional prefix &quot;<strong>!</strong>&quot; which negates the pattern; any matching file excluded by a previous pattern will become included again. It is not possible to re-include a file if a parent directory of that file is excluded. Git doesn&#39;t list excluded directories for performance reasons, so any patterns on contained files have no effect, no matter where they are defined. Put a backslash (&quot;<strong>\\</strong>&quot;) in front of the first &quot;<strong>!</strong>&quot; for patterns that begin with a literal &quot;<strong>!</strong>&quot;, for example, &quot;<strong>\\!important!.txt</strong>&quot;.</p></blockquote><blockquote><p>·</p><p>The slash <em>/</em> is used as the directory separator. Separators may occur at the beginning, middle or end of the <strong>.gitignore</strong> search pattern.</p></blockquote><blockquote><p>·</p><p>If there is a separator at the beginning or middle (or both) of the pattern, then the pattern is relative to the directory level of the particular <strong>.gitignore</strong> file itself. Otherwise the pattern may also match at any level below the <strong>.gitignore</strong> level.</p></blockquote><blockquote><p>·</p><p>If there is a separator at the end of the pattern then the pattern will only match directories, otherwise the pattern can match both files and directories.</p></blockquote><blockquote><p>·</p><p>For example, a pattern <strong>doc/frotz/</strong> matches <strong>doc/frotz</strong> directory, but not <strong>a/doc/frotz</strong> directory; however <strong>frotz/</strong> matches <strong>frotz</strong> and <strong>a/frotz</strong> that is a directory (all paths are relative from the <strong>.gitignore</strong> file).</p></blockquote><blockquote><p>·</p><p>An asterisk &quot;<strong>** *&quot; matches anything except a slash. The character &quot;</strong>?<strong>&quot; matches any one character except &quot;</strong>/**&quot;. The range notation, e.g. <strong>[a-zA-Z]</strong>, can be used to match one of the characters in a range. See fnmatch(3) and the FNM_PATHNAME flag for a more detailed description.</p></blockquote><p>Two consecutive asterisks (&quot;***** *&quot;) in patterns matched against full pathname may have special meaning:</p><blockquote><p>·</p><p>A leading &quot;<strong>*** *&quot; followed by a slash means match in all directories. For example, &quot;</strong>**/foo**&quot; matches file or directory &quot;<strong>foo</strong>&quot; anywhere, the same as pattern &quot;<strong>foo</strong>&quot;. &quot;<strong>**/foo/bar</strong>&quot; matches file or directory &quot;<strong>bar</strong>&quot; anywhere that is directly under directory &quot;<strong>foo</strong>&quot;.</p></blockquote><blockquote><p>·</p><p>A trailing &quot;**/*** *&quot; matches everything inside. For example, &quot;*<em>abc/**</em> *&quot; matches all files inside directory &quot;<strong>abc</strong>&quot;, relative to the location of the <strong>.gitignore</strong> file, with infinite depth.</p></blockquote><blockquote><p>·</p><p>A slash followed by two consecutive asterisks then a slash matches zero or more directories. For example, &quot;<strong>a/**/b</strong>&quot; matches &quot;<strong>a/b</strong>&quot;, &quot;<strong>a/x/b</strong>&quot;, &quot;<strong>a/x/y/b</strong>&quot; and so on.</p></blockquote><blockquote><p>·</p><p>Other consecutive asterisks are considered regular asterisks and will match according to the previous rules.</p></blockquote><h2 id="configuration" tabindex="-1">CONFIGURATION <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;CONFIGURATION&quot;">​</a></h2><p>The optional configuration variable <strong>core.excludesFile</strong> indicates a path to a file containing patterns of file names to exclude, similar to <strong>$GIT_DIR/info/exclude</strong>. Patterns in the exclude file are used in addition to those in <strong>$GIT_DIR/info/exclude</strong>.</p><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>The purpose of gitignore files is to ensure that certain files not tracked by Git remain untracked.</p><p>To stop tracking a file that is currently tracked, use <em>git rm --cached</em>.</p><p>Git does not follow symbolic links when accessing a <strong>.gitignore</strong> file in the working tree. This keeps behavior consistent when the file is accessed from the index or a tree versus from the filesystem.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><blockquote><p>·</p><p>The pattern *<em>hello.*</em> * matches any file or directory whose name begins with <strong>hello.</strong>. If one wants to restrict this only to the directory and not in its subdirectories, one can prepend the pattern with a slash, i.e. *<em>/hello.*</em> *; the pattern now matches <strong>hello.txt</strong>, <strong>hello.c</strong> but not <strong>a/hello.java</strong>.</p></blockquote><blockquote><p>·</p><p>The pattern <strong>foo/</strong> will match a directory <strong>foo</strong> and paths underneath it, but will not match a regular file or a symbolic link <strong>foo</strong> (this is consistent with the way how pathspec works in general in Git)</p></blockquote><blockquote><p>·</p><p>The pattern <strong>doc/frotz</strong> and <strong>/doc/frotz</strong> have the same effect in any <strong>.gitignore</strong> file. In other words, a leading slash is not relevant if there is already a middle slash in the pattern.</p></blockquote><blockquote><p>·</p><p>The pattern &quot;foo/*&quot;, matches &quot;foo/test.json&quot; (a regular file), &quot;foo/bar&quot; (a directory), but it does not match &quot;foo/bar/hello.c&quot; (a regular file), as the asterisk in the pattern does not match &quot;bar/hello.c&quot; which has a slash in it.</p></blockquote><blockquote><pre><code>    $ git status
    [...]
    # Untracked files:
    [...]
    #       Documentation/foo.html
    #       Documentation/gitignore.html
    #       file.o
    #       lib.a
    #       src/internal.o
    [...]
    $ cat .git/info/exclude
    # ignore objects and archives, anywhere in the tree.
    *.[oa]
    $ cat Documentation/.gitignore
    # ignore generated html files,
    *.html
    # except foo.html which is maintained by hand
    !foo.html
    $ git status
    [...]
    # Untracked files:
    [...]
    #       Documentation/foo.html
    [...]
</code></pre></blockquote><p>Another example:</p><blockquote><pre><code>    $ cat .gitignore
    vmlinux*
    $ ls arch/foo/kernel/vm*
    arch/foo/kernel/vmlinux.lds.S
    $ echo &#39;!/vmlinux*&#39; &gt;arch/foo/kernel/.gitignore
</code></pre></blockquote><p>The second .gitignore prevents Git from ignoring <strong>arch/foo/kernel/vmlinux.lds.S</strong>.</p><p>Example to exclude everything except a specific directory <strong>foo/bar</strong> (note the *<em>/*</em> * - without the slash, the wildcard would also exclude everything within <strong>foo/bar</strong>):</p><blockquote><pre><code>    $ cat .gitignore
    # exclude everything except directory foo/bar
    /*
    !/foo
    /foo/*
    !/foo/bar
</code></pre></blockquote><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>git-rm</strong>(1), <strong>gitrepository-layout</strong>(5), <strong>git-check-ignore</strong>(1)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,52);function h(e,g,p,u,d,f){return o(),n("div",null,[r("h1",l,i(e.$params.man),1),c])}const q=t(s,[["render",h]]);export{b as __pageData,q as default};
